                     <button id="confirm-button" class="w-full bg-primary text-white font-bold py-3 px-4 rounded-lg hover:bg-primary focus:outline-none focus:ring-2 focus:ring-primary/50 transition-all disabled:bg-appBorder disabled:text-appSecondaryText disabled:shadow-none">
