        /* --- 设置面板 --- */
        #settingsModalPage .modal-body { display: flex; flex-direction: column; gap: 20px; padding-top: 15px; }
        .theme-cards-container { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 10px; }
