        input[type="range"]::-webkit-slider-runnable-track { width: 100%; height: 6px; cursor: pointer; background: var(--slider-track-color); border-radius: 5px; }
        input[type="range"]::-moz-range-thumb { height: 18px; width: 18px; border-radius: 50%; background: var(--slider-thumb-color); cursor: pointer; border: 2px solid var(--modal-bg); }
