<script>
    const container = document.getElementById('main-container');
    const fontSlider = document.getElementById('font-slider');
    const fontSizeValue = document.getElementById('font-size-value');

    function switchTheme(themeName) {
        container.className = 'main-container ' + themeName;
        document.querySelectorAll('.theme-card').forEach(card => card.classList.remove('active'));
        document.getElementById(`card-${themeName.split('-')[1]}`).classList.add('active');
        closeModal('settingsModalPage');
    }

    function handleFontSlider() {
        const scale = fontSlider.value;
        document.documentElement.style.setProperty('--font-scale', scale);
        fontSizeValue.textContent = `${Math.round(scale * 100)}%`;
    }

    const MAX_RETRIES = 5;
    const RETRY_DELAY = 400;
    let currentRetry = 0;

    function SafeGetValue(data, path, defaultValue = '未知') {
        if (!data) return defaultValue;
        const keys = path.split('.');
        let current = data;
        for (const key of keys) {
            if (current === undefined || current === null || typeof current !== 'object' || !current.hasOwnProperty(key)) {
                return defaultValue;
            }
            current = current[key];
        }
        if (current === undefined || current === null) return defaultValue;
        if (Array.isArray(current) && current.length > 0) {
            const value = current[0];
            return String(value) === '' ? defaultValue : String(value);
        }
        return String(current) === '' ? defaultValue : String(current);
    }

    async function populateData() {
        try {
            if (typeof getChatMessages !== 'function' || typeof getCurrentMessageId !== 'function') { return; }
            const messages = await getChatMessages(getCurrentMessageId());
            const data = messages?.[0]?.data?.stat_data;

            if (!data) {
                if (currentRetry < MAX_RETRIES) {
                    currentRetry++;
                    setTimeout(populateData, RETRY_DELAY);
                } else {
                    document.getElementById('screen-header-time').innerText = "未能加载数据喵QAQ";
                }
                return;
            }

            const world = data.世界;
            document.getElementById('screen-header-time').innerText = 
                `${SafeGetValue(world, '年份')}年${SafeGetValue(world, '月份')}月${SafeGetValue(world, '日期')}日 星期${SafeGetValue(world, '星期')} ${SafeGetValue(world, '具体时间')}`;

            document.querySelectorAll('.room-name[id]').forEach(el => el.innerText = '空');
            const tenantRecords = data.租客档案;
            if(tenantRecords){
                for (const key in tenantRecords) {
                    const tenant = tenantRecords[key];
                    const charName = SafeGetValue(tenant, '角色名');
                    const roomID = SafeGetValue(tenant, '房间ID');
                    if (charName !== '空' && charName !== '未知' && roomID !== '空' && roomID !== '未知') {
                        const roomNameEl = document.getElementById(`room_name_${roomID}`);
                        if (roomNameEl) roomNameEl.innerText = charName;
                    }
                }
            }
        } catch (error) {
            console.error("状态栏加载出错:", error);
            document.getElementById('screen-header-time').innerText = "加载出错了!";
        }
    }

    async function showRoomInfo(roomID) {
        try {
            const messages = await getChatMessages(getCurrentMessageId());
            const data = messages?.[0]?.data?.stat_data;
            if (!data) return;

            const tenantRecords = data.租客档案;
            const charData = data.角色数据;
            const roomModalPage = document.getElementById('roomModalPage');

            let occupantKey = null;
            if (tenantRecords) {
                for (const key in tenantRecords) {
                    if (SafeGetValue(tenantRecords[key], '房间ID') === roomID && SafeGetValue(tenantRecords[key], '角色名') !== '空') {
                        occupantKey = key;
                        break;
                    }
                }
            }

            if (occupantKey && charData && charData[occupantKey]) {
                const char = charData[occupantKey];
                roomModalPage.innerHTML = `
                    <div class="modal-header" onclick="closeModal('roomModalPage')">
                        <h3 class="modal-title">${SafeGetValue(char, '姓名')}</h3>
                    </div>
                    <div class="modal-body">
                        <div class="char-info-container">
                            <div class="char-info-grid">
                                <strong>姓名:</strong> <span>${SafeGetValue(char, '姓名')}</span>
                                <strong>年龄:</strong> <span>${SafeGetValue(char, '年龄')}</span>
                                <strong>职业:</strong> <span>${SafeGetValue(char, '职业')}</span>
                                <strong>性格:</strong> <span>${SafeGetValue(char, '性格')}</span>
                                <strong>恋情:</strong> <span>${SafeGetValue(char, '恋情状态')}</span>
                                <strong>心情:</strong> <span>${SafeGetValue(char, '心情')}</span>
                                <strong>状态:</strong> <span>${SafeGetValue(char, '当前状态')}</span>
                            </div>
                            <div class="progress-section">
                                <div class="char-info-grid" style="gap: 5px 15px;">
                                    <strong>❤️ 好感度:</strong> <span>${SafeGetValue(char, '好感度')}/100</span>
                                </div>
                                <div class="progress-bar-container"><div class="progress-bar" style="background: #E91E63; width: ${SafeGetValue(char, '好感度', 0)}%;"></div></div>
                            </div>
                            <div class="progress-section">
                                <div class="char-info-grid" style="gap: 5px 15px;">
                                    <strong>🔥 性欲:</strong> <span>${SafeGetValue(char, '性欲')}/100</span>
                                </div>
                                <div class="progress-bar-container"><div class="progress-bar" style="background: #FF5722; width: ${SafeGetValue(char, '性欲', 0)}%;"></div></div>
                            </div>
                            <hr class="char-separator">
                            <div class="char-info-grid">
                                <strong>🍒胸部:</strong> <span>${SafeGetValue(char, '胸部')}</span>
                                <strong>👙内衣:</strong> <span>${SafeGetValue(char, '内衣')}</span>
                                <strong>🩲内裤:</strong> <span>${SafeGetValue(char, '内裤')}</span>
                                <strong>🌸小穴:</strong> <span>${SafeGetValue(char, '小穴')}</span>
                                <strong>🍑肛门:</strong> <span>${SafeGetValue(char, '肛门')}</span>
                            </ul>
                        </div>
                    </div>`;
                roomModalPage.classList.add('visible');
            }
        } catch (e) { console.error("打开房间信息时出错: ", e); }
    }

    async function showTasksModal() {
        try {
            const messages = await getChatMessages(getCurrentMessageId());
            const data = messages?.[0]?.data?.stat_data;
            if (!data) return;
            const world = data.世界;
            const tasksModalPage = document.getElementById('tasksModalPage');
            tasksModalPage.innerHTML = `
                <div class="modal-header" onclick="closeModal('tasksModalPage')">
                    <h3 class="modal-title">任务清单</h3>
                </div>
                <div class="modal-body">
                    <h4 style="color:var(--task-urgent-color, #F28B82);">❗️ 紧急任务</h4>
                    <ul style="list-style: none; padding: 0;">
                        <li style="background:var(--room-bg); padding:10px; border-radius:8px; margin-bottom:8px; border-left: 4px solid var(--task-urgent-color, #F28B82);">${SafeGetValue(world, '紧急任务1', '暂无')}</li>
                        <li style="background:var(--room-bg); padding:10px; border-radius:8px; margin-bottom:8px; border-left: 4px solid var(--task-urgent-color, #F28B82);">${SafeGetValue(world, '紧急任务2', '暂无')}</li>
                    </ul>
                    <h4 style="color:var(--task-normal-color, #81C995); margin-top: 20px;">💬 普通任务</h4>
                    <ul style="list-style: none; padding: 0;">
                        <li style="background:var(--room-bg); padding:10px; border-radius:8px; margin-bottom:8px; border-left: 4px solid var(--task-normal-color, #81C995);">${SafeGetValue(world, '普通任务1', '暂无')}</li>
                    </ul>
                </div>`;
            tasksModalPage.classList.add('visible');
        } catch (e) { console.error("打开任务列表时出错: ", e); }
    }

    function recruitTenant() {
        const features = prompt("请输入您希望新租客拥有的特征（或留空）：", "");
        if (features !== null) {
            const messageContent = `招募租客\n需要的特征为：(${features})`;
            const escapedMessage = messageContent.replace(/\"/g, '\\"');
            const command = `/send "${escapedMessage}" | /trigger await=true`;
            if (typeof triggerSlash === 'function') {
                triggerSlash(command);
            } else {
                console.error("SillyTavern's triggerSlash function not found.");
                alert(`模拟发送指令 (请在SillyTavern环境中运行):\\n${command}`);
            }
        }
    }

    function showSettingsModal() { document.getElementById('settingsModalPage').classList.add('visible'); }
    function closeModal(modalId) {
        const modal = document.getElementById(modalId);
        if(modal) modal.classList.remove('visible');
    }

    document.addEventListener('DOMContentLoaded', () => {
        populateData();
        document.getElementById('recruitBtn').addEventListener('click', recruitTenant);
        fontSlider.addEventListener('input', handleFontSlider);
        const currentTheme = container.className.split(' ')[1] || 'theme-modern';
        document.querySelectorAll('.theme-card').forEach(card => card.classList.remove('active'));
        document.getElementById(`card-${currentTheme.split('-')[1]}`).classList.add('active');
    });

</script>
</body>
